public final class QuantNewPeriodReplay {
    static final LocalDate CUTOFF=LocalDate.parse("2026-04-30");
    static final List<LocalDate> DATES=List.of(CUTOFF,LocalDate.parse("2026-05-29"));
    static final String CONTEXT="tmp/quant-restandardized-all20-20261031/frozen-context.json";
    static final String INPUT="tmp/quant-restandardized-prepared-v2-20261031/inputs.json";
    static final String EXPANSION="tmp/quant-prepanel-financial-expansion-20261031-v1/new-standards-by-symbol.json";
    static final String V8="EXPECTED_RETURN_V8_CORRECTED_20261017";
    static ObjectMapper json=new ObjectMapper();
    static boolean mature(StockBacktestResult r,LocalDate cutoff){return r.getSignalDate()!=null&&r.getExitTradeDate()!=null&&r.getSignalDate().isBefore(cutoff)&&r.getExitTradeDate().isBefore(cutoff);}
    static List<LocalDate> holdingDates(List<LocalDate> calendar,LocalDate decision){var after=calendar.stream().filter(d->d.isAfter(decision)).sorted().distinct().limit(21).toList();if(after.size()!=21)throw new IllegalArgumentException("Incomplete21session horizon");return after;}
    static List<StockCandleDaily> mergePrices(List<StockCandleDaily> canonical,List<StockCandleDaily> supplement){
        var rows=new TreeMap<LocalDate,StockCandleDaily>();for(var c:canonical)require(rows.put(c.getTradeDate(),c)==null,"Duplicate canonical price day");var seen=new HashSet<LocalDate>();
        for(var c:supplement){require(c.getTradeDate()!=null&&c.getClosePrice()!=null&&c.getClosePrice().signum()>0&&seen.add(c.getTradeDate()),"Invalid/duplicate source price day");var old=rows.get(c.getTradeDate());if(old==null)rows.put(c.getTradeDate(),c);else require(old.getSymbol().equals(c.getSymbol())&&old.getClosePrice().subtract(c.getClosePrice()).abs().compareTo(new BigDecimal("0.00002"))<=0,"Canonical/free source price basis conflict");}return new ArrayList<>(rows.values());
    }
    static void require(boolean ok,String message){if(!ok)throw new IllegalStateException(message);}
    static JsonNode read(String p)throws Exception{return json.readTree(Files.readString(Path.of(p)));}
    static <T> List<T> list(JsonNode n,Class<T> cls){var rows=new ArrayList<T>();for(var v:n)rows.add(json.treeToValue(v,cls));return rows;}
    static void write(Path p,Object value)throws Exception{Files.writeString(p,json.writerWithDefaultPrettyPrinter().writeValueAsString(value),StandardOpenOption.CREATE_NEW);}
    static void factors(StockSignalSnapshot s,StockBacktestResult r)throws Exception{for(String factor:QuantRestandardizedReplay.FACTORS){var value=StockSignalSnapshot.class.getMethod("get"+factor+"Score").invoke(s);StockBacktestResult.class.getMethod("set"+factor+"Score",Integer.class).invoke(r,value);}r.setIntegratedScore(s.getIntegratedScore());}
    static void rerank(List<StockBacktestResult> rows)throws Exception{
        var byDay=new TreeMap<LocalDate,List<StockBacktestResult>>();for(var r:rows)byDay.computeIfAbsent(r.getSignalDate(),k->new ArrayList<>()).add(r);
        for(var day:byDay.values()){var signals=new ArrayList<StockSignalSnapshot>();for(var r:day)signals.add(QuantRestandardizedReplay.oldSignal(r));QuantRestandardizedReplay.rank(signals);for(int i=0;i<day.size();i++)day.get(i).setIntegratedScore(signals.get(i).getIntegratedScore());}
    }
    static List<String> population(JsonNode input,LocalDate day){var set=new TreeSet<String>();for(var n:input.path("dates").path("2026-03-27"))set.add(n.asText());require(set.size()==101&&set.remove("TEAM"),"Expected March101member roster includes TEAM");require(set.add("SNDK"),"Unexpected existing SNDK");if(day.equals(DATES.get(1))){require(set.remove("CSGP")&&set.add("LITE"),"May CSGP/LITE transition");}return List.copyOf(set);}
    static SecFinancialStandard lookup(HistoricalBacktestSeedMapper seed,String method,String symbol,LocalDate before,LocalDate day)throws Exception{
        return switch(method){case "findLatestAnnualAsOf"->seed.findLatestAnnualAsOf(symbol,day);case "findPreviousAnnualAsOf"->seed.findPreviousAnnualAsOf(symbol,before,day);case "findLatestQuarterAsOf"->seed.findLatestQuarterAsOf(symbol,day);case "findPreviousQuarterAsOf"->seed.findPreviousQuarterAsOf(symbol,before,day);default->throw new IllegalArgumentException(method);};
    }
    static HistoricalBacktestSeedMapper overlay(HistoricalBacktestSeedMapper real,Map<String,List<SecFinancialStandard>> additions,Map<String,Object> audit){
        return (HistoricalBacktestSeedMapper)Proxy.newProxyInstance(QuantNewPeriodReplay.class.getClassLoader(),new Class[]{HistoricalBacktestSeedMapper.class},(p,m,a)->{
            String method=m.getName();if(method.contains("AnnualAsOf")||method.contains("QuarterAsOf")){
                boolean previous=method.contains("Previous"),annual=method.contains("Annual");String symbol=(String)a[0];LocalDate day=(LocalDate)a[previous?2:1];LocalDate before=previous?(LocalDate)a[1]:null;
                var nativeRow=lookup(real,method,symbol,before,day);var choices=new ArrayList<SecFinancialStandard>(additions.getOrDefault(symbol,List.of()));if(nativeRow!=null)choices.add(nativeRow);
                var selected=QuantMatchedFinancialReplay.select(choices,annual,before,day);audit.put(symbol+"/"+day+"/"+method,selected==null?Map.of("missing",true):json.convertValue(selected,SecFinancialStandard.class));return selected;
            }
            require(Set.of("findCandlesOnOrBefore","findRecommendationAsOf","findInstitutionFlowAsOf","findNewsStatsAsOf").contains(method),"Unexpected read method "+method);return m.invoke(real,a);
        });
    }
    static StockMarketSnapshot market(JdbcTemplate db,HistoricalBacktestSeedMapper seed,String symbol,LocalDate day,Map<String,Object> audit)throws Exception{
        var candidates=db.queryForList("SELECT id,symbol,cik,taxonomy,concept,unit,accession_number,filed_at,end_date,value,raw_json FROM stock_sec_fact WHERE symbol=? AND unit='shares' AND filed_at<? AND end_date<? AND (start_date IS NULL OR start_date=end_date) AND concept IN ('EntityCommonStockSharesOutstanding','CommonStockSharesOutstanding','NumberOfSharesOutstanding') AND value>0 ORDER BY end_date DESC,filed_at DESC,id DESC LIMIT 80",symbol,day,day);
        Map<String,Object> chosen=null;
        for(var r:candidates){var raw=json.readTree(String.valueOf(r.get("raw_json")));if(raw.has("start"))continue;if(!String.valueOf(r.get("accession_number")).equals(raw.path("accn").asText())||!String.valueOf(r.get("filed_at")).equals(raw.path("filed").asText())||!String.valueOf(r.get("end_date")).equals(raw.path("end").asText()))continue;if(new BigDecimal(String.valueOf(r.get("value"))).compareTo(new BigDecimal(raw.path("val").asText()))!=0)continue;chosen=r;break;}
        var result=new StockMarketSnapshot();result.setSymbol(symbol);result.setIndexCode(QuantRestandardizedReplay.SOURCE);result.setSnapshotDate(day);result.setCurrency("USD");result.setPriceSource("CANONICAL_STORED_CLOSE_RESEARCH");result.setCalculatedAt(LocalDateTime.now());
        var bars=seed.findCandlesOnOrBefore(symbol,day,1);require(bars.size()==1&&bars.getFirst().getTradeDate().equals(day),"Missing actual decision close "+symbol+day);result.setClosePrice(bars.getFirst().getClosePrice());
        if(chosen==null){result.setSharesSource("MISSING_PRIOR_RAW_SHARES");result.setMarketCapSource("MISSING_PRIOR_RAW_SHARES");audit.put(symbol+"/"+day,Map.of("missing",true));return result;}
        var shares=new BigDecimal(String.valueOf(chosen.get("value")));result.setSharesOutstanding(shares);result.setMarketCapUsd(shares.multiply(result.getClosePrice()));result.setSharesSource("SEC_XBRL_PRIOR_RAW_INSTANT_RESEARCH");result.setMarketCapSource("SEC_XBRL_PRIOR_SHARES_X_CANONICAL_CLOSE_RESEARCH");audit.put(symbol+"/"+day,chosen);return result;
    }
    /** Same captured production stages as QuantRestandardizedReplay.models; partialV9 retained as diagnostics, never repaired with fabricated caps. */
    static List<StockExpectedReturnSnapshot> models(LocalDate day,List<StockBacktestResult> target,List<StockBacktestResult> source,List<StockExpectedReturnSnapshot> existing,List<StockBenchmarkReturn> benchmark,List<StockMacroFeatureSnapshot> macro,List<StockMarketSnapshot> market)throws Exception{
        var working=new ArrayList<StockBacktestResult>();for(var r:source)if(r.getSignalDate().isBefore(day))working.add(json.convertValue(r,StockBacktestResult.class));working.addAll(target);
        var state=new LinkedHashMap<String,StockExpectedReturnSnapshot>();for(var p:existing)if(p.getSignalDate().isBefore(day)){var c=json.convertValue(p,StockExpectedReturnSnapshot.class);c.setIndexCode(QuantRestandardizedReplay.RESEARCH);state.put(QuantRestandardizedReplay.key(c),c);}
        StockBacktestMapper memory=(StockBacktestMapper)Proxy.newProxyInstance(QuantNewPeriodReplay.class.getClassLoader(),new Class[]{StockBacktestMapper.class},(p,m,a)->{
            String name=m.getName();if(name.equals("findResults"))return working;
            if(name.equals("findBenchmarkReturns"))return benchmark.stream().map(b->{var c=json.convertValue(b,StockBenchmarkReturn.class);c.setIndexCode(QuantRestandardizedReplay.RESEARCH);return c;}).toList();
            if(name.equals("findExpectedReturnSnapshots"))return state.values().stream().filter(s->!s.getSignalDate().isBefore((LocalDate)a[1])&&!s.getSignalDate().isAfter((LocalDate)a[2])).toList();
            if(name.equals("findMacroRegimeSnapshots"))return List.of();if(name.equals("findMacroFeatureSnapshots"))return macro.stream().filter(f->!f.getSnapshotDate().isAfter(day)).toList();
            if(name.equals("findMarketSnapshots"))return market.stream().filter(s->!s.getSnapshotDate().isBefore((LocalDate)a[1])&&!s.getSnapshotDate().isAfter((LocalDate)a[2])).toList();
            if(name.equals("upsertExpectedReturnSnapshot")){var s=(StockExpectedReturnSnapshot)a[0];require(QuantRestandardizedReplay.RESEARCH.equals(s.getIndexCode())&&day.equals(s.getSignalDate()),"Out of scope model write");s.setCalculatedAt(LocalDateTime.now());state.put(QuantRestandardizedReplay.key(s),s);}
            else if(!Set.of("deleteExpectedReturnFactorContributions","copyExpectedReturnFactorContributions","upsertFactorExposureSnapshot","upsertExpectedReturnFactorContribution","deleteExpectedReturnCalibrations","upsertExpectedReturnCalibration").contains(name))throw new IllegalStateException("Unexpected model operation "+name);
            return m.getReturnType()==void.class?null:1;
        });
        var beans=new StaticListableBeanFactory();beans.addBean("mapper",memory);var provider=beans.getBeanProvider(StockBacktestMapper.class);var service=new StockPortfolioBacktestService(provider,json,0);
        service.refreshExpectedReturnSnapshots(QuantRestandardizedReplay.RESEARCH,200000,1,300);service.refreshExpectedReturnV3Snapshots(QuantRestandardizedReplay.RESEARCH,200000,1,300);service.refreshExpectedReturnV4Snapshots(QuantRestandardizedReplay.RESEARCH,200000,1,300);service.refreshExpectedReturnV5Snapshots(QuantRestandardizedReplay.RESEARCH,200000,1,300);service.refreshExpectedReturnV6Snapshots(QuantRestandardizedReplay.RESEARCH,200000,1,300);service.refreshExpectedReturnV7Snapshots(QuantRestandardizedReplay.RESEARCH,200000,1,300);new StockExpectedReturnV8Service(provider).refreshHistorical(QuantRestandardizedReplay.RESEARCH,200000,1);new StockExpectedReturnV9Service(provider).refreshHistorical(QuantRestandardizedReplay.RESEARCH,200000,1);
        var result=state.values().stream().filter(p->day.equals(p.getSignalDate())&&Integer.valueOf(20).equals(p.getHorizonDays())).toList();
        for(int v=2;v<=8;v++){String version="EXPECTED_RETURN_V"+v+"_CORRECTED_20261017";require(result.stream().filter(p->version.equals(p.getModelVersion())).count()==101,"Incomplete full V2-V8 population "+version);}
        return result;
    }
    public static void main(String[] args)throws Exception{
        require(args.length==3||args.length==4,"Usage: sealed protocol expectedSHA NEW_OUTPUT_DIR [holding-price-overlay]");Path protocol=Path.of(args[0]),out=Path.of(args[2]);require(Files.exists(protocol)&&QuantRestandardizedReplay.sha(protocol.toString()).equals(args[1]),"Protocol not sealed at expected hash");require(!Files.exists(out),"Refuse overwrite");
        var protocolNode=read(protocol.toString());require(protocolNode.toString().contains("2026-04-30")&&protocolNode.toString().contains("2026-05-29"),"Protocol does not cover fixed dates");
        var hashes=new TreeMap<String,String>();for(String p:List.of(protocol.toString(),CONTEXT,INPUT,EXPANSION,"scripts/QuantNewPeriodReplay.java","scripts/QuantRestandardizedReplay.java","scripts/QuantMatchedFinancialReplay.java"))hashes.put(p,QuantRestandardizedReplay.sha(p));
        JsonNode priceOverlay=args.length==4?read(args[3]):json.createObjectNode();if(args.length==4){hashes.put(args[3],QuantRestandardizedReplay.sha(args[3]));for(var e:priceOverlay.path("inputHashes").properties()){require(QuantRestandardizedReplay.sha(e.getKey()).equals(e.getValue().asText()),"Price overlay dependency drift "+e.getKey());hashes.put(e.getKey(),e.getValue().asText());}}
        var context=read(CONTEXT);var input=read(INPUT);var expansion=read(EXPANSION);var additions=new TreeMap<String,List<SecFinancialStandard>>();for(var e:expansion.properties())additions.put(e.getKey(),list(e.getValue(),SecFinancialStandard.class));
        var source=list(context.path("source"),StockBacktestResult.class).stream().filter(r->Integer.valueOf(20).equals(r.getHorizonDays())&&mature(r,CUTOFF)).toList();var oldTraining=new ArrayList<StockBacktestResult>();var newTraining=new ArrayList<StockBacktestResult>();for(var r:source){oldTraining.add(json.convertValue(r,StockBacktestResult.class));newTraining.add(json.convertValue(r,StockBacktestResult.class));}
        var existing=list(context.path("existing"),StockExpectedReturnSnapshot.class).stream().filter(r->r.getSignalDate().isBefore(CUTOFF)).toList();var benchmark=list(context.path("benchmark"),StockBenchmarkReturn.class);var macro=list(context.path("macro"),StockMacroFeatureSnapshot.class);var calendar=benchmark.stream().map(StockBenchmarkReturn::getTradeDate).distinct().sorted().toList();
        QuantRestandardizedReplay.json=json;QuantRestandardizedLeakageCheck.json=json;QuantMatchedFinancialReplay.json=json;QuantMatchedFinancialReplay.validPeriod=Class.forName("com.kingyurina.demo.stock.FinancialInputPolicy").getDeclaredMethod("validPeriod",SecFinancialStandard.class,boolean.class);QuantMatchedFinancialReplay.validPeriod.setAccessible(true);
        for(int i=0;i<source.size();i++){var r=source.get(i);var b=CompleteBenchmarkReturn.compound(benchmark,QuantRestandardizedReplay.SOURCE,r.getEntryTradeDate(),r.getExitTradeDate(),20);require(b!=null,"Training benchmark missing "+r.getSignalDate()+r.getSymbol());oldTraining.get(i).setBenchmarkReturnPct(BigDecimal.valueOf(b));newTraining.get(i).setBenchmarkReturnPct(BigDecimal.valueOf(b));}
        var app=new SpringApplication(CodexDemoApplication.class);app.setWebApplicationType(WebApplicationType.NONE);
        try(var ctx=app.run("--spring.profiles.active=mariadb","--spring.sql.init.mode=never","--spring.datasource.hikari.read-only=true","--spring.datasource.hikari.connection-init-sql=SET SESSION TRANSACTION READ ONLY","--app.signal.refresh.enabled=false","--app.signal.refresh.run-on-startup=false")){
            var db=ctx.getBean(JdbcTemplate.class);require(db.queryForObject("SELECT @@tx_read_only",Integer.class)==1,"Database not read-only");var before=QuantRestandardizedReplay.databaseState(db);var seed=ctx.getBean(HistoricalBacktestSeedMapper.class);var builder=ctx.getBean(HistoricalBacktestSeedService.class);var build=HistoricalBacktestSeedService.class.getDeclaredMethod("buildSnapshot",HistoricalBacktestSeedMapper.class,String.class,LocalDate.class);build.setAccessible(true);
            var financialReads=new TreeMap<String,Object>();var trainingFinancialReads=new TreeMap<String,Object>();var patched=overlay(seed,additions,trainingFinancialReads);int rebuilt=0,changed=0;
            for(var r:newTraining){if(!r.getSignalDate().isBefore(LocalDate.parse("2024-07-31"))||additions.getOrDefault(r.getSymbol(),List.of()).isEmpty())continue;
                var fresh=(StockSignalSnapshot)build.invoke(builder,patched,r.getSymbol(),r.getSignalDate());require(fresh!=null,"Cannot rebuild prepanel training "+r.getSymbol()+r.getSignalDate());boolean affected=false;
                for(String factor:List.of("Valuation","Quality","Growth","Stability","Earnings")){var value=StockSignalSnapshot.class.getMethod("get"+factor+"Score").invoke(fresh);var getter=StockBacktestResult.class.getMethod("get"+factor+"Score");if(!Objects.equals(getter.invoke(r),value))affected=true;StockBacktestResult.class.getMethod("set"+factor+"Score",Integer.class).invoke(r,value);}rebuilt++;if(affected)changed++;
            }
            rerank(oldTraining);rerank(newTraining);var sourceHashOld=QuantRestandardizedReplay.objectHash(oldTraining);var sourceHashNew=QuantRestandardizedReplay.objectHash(newTraining);
            var dates=new ArrayList<Object>();var baselinePredictions=new ArrayList<StockExpectedReturnSnapshot>();var predictionsAll=new ArrayList<StockExpectedReturnSnapshot>();var marketReads=new TreeMap<String,Object>();var targetMarkets=new ArrayList<StockMarketSnapshot>();
            var trainingAudit=Map.of("fixedCutoffExclusive",CUTOFF,"matureTrainingRows20D",source.size(),"uniqueTrainingSignalDates",source.stream().map(StockBacktestResult::getSignalDate).distinct().count(),"maxTrainingSignal",source.stream().map(StockBacktestResult::getSignalDate).max(LocalDate::compareTo).orElseThrow(),"maxTrainingExit",source.stream().map(StockBacktestResult::getExitTradeDate).max(LocalDate::compareTo).orElseThrow(),"newFinancialRebuiltTrainingRows",rebuilt,"changedFinancialScoreTrainingRows",changed,"holdoutLabelsRolledIntoTraining",0);
            for(var day:DATES){
                require(QuantRestandardizedReplay.sha(protocol.toString()).equals(args[1]),"Sealed protocol changed");var symbols=population(input,day);var holding=holdingDates(calendar,day);var signals=new ArrayList<StockSignalSnapshot>();var markets=new ArrayList<StockMarketSnapshot>();var missingCaps=new ArrayList<String>();
                HistoricalBacktestSeedMapper audited=overlay(seed,Map.of(),financialReads);
                for(String symbol:symbols){var signal=(StockSignalSnapshot)build.invoke(builder,audited,symbol,day);require(signal!=null,"Cannot build new target "+symbol+day);signals.add(signal);var market=market(db,seed,symbol,day,marketReads);markets.add(market);if(market.getMarketCapUsd()==null)missingCaps.add(symbol);}
                QuantRestandardizedReplay.rank(signals);targetMarkets.addAll(markets);var targets=new ArrayList<StockBacktestResult>();var pairs=new ArrayList<Map<String,Object>>();
                var b=CompleteBenchmarkReturn.compound(benchmark,QuantRestandardizedReplay.SOURCE,holding.getFirst(),holding.getLast(),20);require(b!=null,"Missing holding benchmark");
                for(var signal:signals){String symbol=signal.getSymbol();var bars=db.query("SELECT trade_date,close_price,source FROM stock_candle_daily WHERE symbol=? AND trade_date>=? AND trade_date<=? ORDER BY trade_date",(rs,n)->{var c=new StockCandleDaily();c.setSymbol(symbol);c.setTradeDate(rs.getDate(1).toLocalDate());c.setClosePrice(rs.getBigDecimal(2));c.setSource(rs.getString(3));return c;},symbol,holding.getFirst(),holding.getLast());
                    var supplement=new ArrayList<StockCandleDaily>();for(var n:priceOverlay.path("bySymbol").path(symbol)){var d=LocalDate.parse(n.path("day").asText());if(d.isBefore(holding.getFirst())||d.isAfter(holding.getLast()))continue;var c=new StockCandleDaily();c.setSymbol(symbol);c.setTradeDate(d);c.setClosePrice(new BigDecimal(n.path("close").asText()));c.setSource(n.path("source").asText("NEW_FREE_PROVIDER_GAP_ONLY_OVERLAP_CHECKED"));supplement.add(c);}if(!supplement.isEmpty())bars=mergePrices(bars,supplement);
                    require(bars.size()==21&&bars.stream().map(StockCandleDaily::getTradeDate).toList().equals(holding)&&bars.stream().allMatch(c->c.getClosePrice()!=null&&c.getClosePrice().signum()>0),"Incomplete positive holding history "+symbol+day);
                    var m=markets.stream().filter(x->symbol.equals(x.getSymbol())).findFirst().orElseThrow();var result=QuantRestandardizedReplay.outcome(signal,bars.getFirst(),bars.getLast(),null,m);result.setBenchmarkReturnPct(BigDecimal.valueOf(b));targets.add(result);var pair=new LinkedHashMap<String,Object>();pair.put("symbol",symbol);pair.put("entry",holding.getFirst());pair.put("exit",holding.getLast());pair.put("entryClose",bars.getFirst().getClosePrice());pair.put("exitClose",bars.getLast().getClosePrice());pair.put("actual",result.getForwardReturnPct());pair.put("benchmark",b);pairs.add(pair);
                }
                System.out.println("NEW_PERIOD_START "+day+" target=101 missingCap="+missingCaps);
                var old=models(day,targets,oldTraining,existing,benchmark,macro,markets);var next=models(day,targets,newTraining,existing,benchmark,macro,markets);
                var altered=new ArrayList<StockBacktestResult>();for(var r:targets){var c=json.convertValue(r,StockBacktestResult.class);c.setForwardReturnPct(BigDecimal.valueOf(-50));c.setBenchmarkReturnPct(BigDecimal.valueOf(50));altered.add(c);}
                var oldPerturbed=models(day,altered,oldTraining,existing,benchmark,macro,markets);var newPerturbed=models(day,altered,newTraining,existing,benchmark,macro,markets);require(QuantRestandardizedLeakageCheck.normalized(old).equals(QuantRestandardizedLeakageCheck.normalized(oldPerturbed))&&QuantRestandardizedLeakageCheck.normalized(next).equals(QuantRestandardizedLeakageCheck.normalized(newPerturbed)),"Future holdout label leak");
                for(var pair:pairs){String symbol=String.valueOf(pair.get("symbol"));var o=old.stream().filter(p->symbol.equals(p.getSymbol())&&V8.equals(p.getModelVersion())).findFirst().orElseThrow();var n=next.stream().filter(p->symbol.equals(p.getSymbol())&&V8.equals(p.getModelVersion())).findFirst().orElseThrow();pair.put("oldAbsolute",o.getExpectedReturnPct());pair.put("oldExcess",o.getExpectedExcessReturnPct());pair.put("newAbsolute",n.getExpectedReturnPct());pair.put("newExcess",n.getExpectedExcessReturnPct());}
                var counts=new TreeMap<String,Integer>();for(var p:next)counts.merge(p.getModelVersion(),1,Integer::sum);
                dates.add(Map.of("decision",day,"pairs",pairs,"newSignals",signals,"missingMarketCapSymbols",missingCaps,"completeV9InputPopulation",missingCaps.isEmpty(),"comparisonModelVersion",V8,"modelCounts",counts,"futureLabelsInvariant",true));baselinePredictions.addAll(old);predictionsAll.addAll(next);System.out.println("NEW_PERIOD_DONE "+day+" predictions="+next.size());
            }
            require(sourceHashOld.equals(QuantRestandardizedReplay.objectHash(oldTraining))&&sourceHashNew.equals(QuantRestandardizedReplay.objectHash(newTraining)),"Training mutated");var after=QuantRestandardizedReplay.databaseState(db);require(before.equals(after),"DB state drift");for(var e:hashes.entrySet())require(QuantRestandardizedReplay.sha(e.getKey()).equals(e.getValue()),"Input drift "+e.getKey());
            Files.createDirectories(out);var report=new LinkedHashMap<String,Object>();report.put("classification","NEW_TARGET_DATES_FIXED_CUTOFF_PAIRED_FINANCIAL_TRAINING_REPAIR_RECONSTRUCTED_NOT_PRISTINE_HOLDOUT");report.put("protocolSha256",args[1]);report.put("comparisonModelVersion",V8);report.put("v9FullPopulationEvaluationAllowed",false);report.put("dates",dates);report.put("trainingOld",oldTraining);report.put("trainingNew",newTraining);report.put("baselinePredictions",baselinePredictions);report.put("predictions",predictionsAll);report.put("trainingAudit",trainingAudit);report.put("financialReads",financialReads);report.put("trainingFinancialReads",trainingFinancialReads);report.put("marketReads",marketReads);report.put("markets",targetMarkets);report.put("inputHashes",hashes);report.put("databaseWrites",0);report.put("sourceDatabaseBefore",before);report.put("sourceDatabaseAfter",after);report.put("promotionAllowed",false);
            report.put("limitations",List.of("New evaluation dates were not stored as prior model/backtest outcomes, but prior researcher knowledge cannot be disproved; not a pristine holdout.","Historical universe is March roster plus official April/May transitions; full constituent-chain, receipt timing, sectors, prices and share/quoted-security basis are reconstructed not certified PIT.","Both training arms rerank the same saved partial date populations; this differs from the saved integrated-score baseline and does not prove complete historical membership.","Only eligible existing prepanel foreign rows can use97new financial statements; all other saved factors remain frozen.","Both dates use the same strictly pre-April30training; no April/May holdout outcomes roll into training. No learned weights or model promotion.","Raw SEC instant shares are prior-filed source observations, not proof of ADR/class/float equivalence. Missing cap days remain diagnostics, not complete evaluation."));
            write(out.resolve("result.json"),report);Files.copy(Path.of("scripts/QuantNewPeriodReplay.java"),out.resolve("QuantNewPeriodReplay.java.source"));System.out.println("NEW_PERIOD_ALL_DONE rows="+baselinePredictions.size()+" training="+source.size()+" financialChanged="+changed);
        }
    }
}
